Definition P_FUZZ_ENTRY : Z := 0x2b3e0.      (* [comment removed for export] *)
Definition P_FUZZ_EMPTY : Z := 0x90c80.      (* [comment removed for export] *)
(* [comment removed for export] *)
Definition FUZZ_STACK : Z := 32768.
(* [comment removed for export] *)
Definition FUZZ_LIVE : Z := 2^28.
Definition FUZZ_CNT : Z := 2100.

(* [comment removed for export] *)
Definition XH_LO : Z := 0x90d30.
Definition XH_HI : Z := 0x91af0.
Definition XH_X : list (Z * Z) := [(XH_LO, XH_HI)].
(* [comment removed for export] *)
Definition XRELRO_LO : Z := 0x7a000.  Definition XRELRO_HI : Z := 0x7f808.
Definition XDATA_LO : Z := 0x80870.   Definition XDATA_HI : Z := 0x80a20.

Lemma XH_consts : XH_LO = G_HTTP_CAT /\ G_HTTP_CAT + 56 = G_HTTP_CAT_GUARD /\ G_HTTP_CAT_GUARD + 8 = G_FIELD_TABLE
                  /\ G_FIELD_TABLE + 3448 = G_FIELD_TABLE_GUARD /\ G_FIELD_TABLE_GUARD + 8 = XH_HI.
Proof. repeat split; reflexivity. Qed.

