(* [comment removed for export] *)
Definition pristine (m : mem) (lo hi : Z) : Prop := forall a, lo <= a < hi -> m (wa a) = None.
Definition XImg (m : mem) : Prop := pristine m XRELRO_LO XRELRO_HI /\ pristine m XDATA_LO XDATA_HI.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Definition FieldTabZero (m : mem) : Prop :=
  rw_cells rsegs m G_FIELD_TABLE [CB 3448 (zeros 3448)] /\ rw_cells rsegs m G_FIELD_TABLE_GUARD [CB 8 (zeros 8)].

(* [comment removed for export] *)
Definition ft_local (FT : mem -> Prop) : Prop :=
  forall m m', FT m -> (forall a, XH_LO <= a < XH_HI -> m' (wa a) = m (wa a)) -> FT m'.

(* [comment removed for export] *)
Definition HStat (FT : mem -> Prop) (m : mem) : Prop :=
  (exists hb : bool, HttpCat m hb) /\ (FieldTabZero m \/ FT m).

