(* [comment removed for export] *)
Section W.
  Variable H : hsr.
  Variable FT : mem -> Prop.

  Definition fuzz_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (LB' : list block),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m' /\ Permutation LB' LB
      /\ HStat FT m'
      /\ xpres LB (bv_unsigned sp) XH_X m m'.

  Definition fuzz_stmt_with : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (D N lo B : Z) (ds : list byte) (errv : word),
      a0 = Z_to_bv 64 D -> a1 = Z_to_bv 64 N ->
      (* [comment removed for export] *)
      bytes_at rsegs m D ds -> Z.of_nat (length ds) = N -> N < 2^26 -> D mod 16 = 0 ->
      (1 <= N -> exists pD, In (pD, D, N) LB) -> (N = 0 -> D = P_FUZZ_EMPTY) ->
      (* [comment removed for export] *)
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + FUZZ_LIVE <= hs_LIVE_MAX H -> Z.of_nat (length LB) + FUZZ_CNT <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> B < 2^64 ->
      (* [comment removed for export] *)
      bv_unsigned sp mod 16 = 0 ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - FUZZ_STACK ->
      (* [comment removed for export] *)
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      XImg m -> CanaryReads m -> HStat FT m ->
      bv_unsigned ra mod 2 = 0 ->
      (* [comment removed for export] *)
      F = bvmap_empty -> fc = Z_to_bv 32 0 ->
      hs_SR H (fuzz_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_FUZZ_ENTRY) fc None m (seg_rom rsegs)) mo).
End W.

(* [comment removed for export] *)
Definition fuzz_stmt (H : hsr) : Prop :=
  exists FT : mem -> Prop, ft_local FT /\ fuzz_stmt_with H FT.

