(* [comment removed for export] *)
Lemma rw_cells_agree : forall m m' A cs,
  rw_cells rsegs m A cs ->
  (forall a, A <= a < A + Z.of_nat (cells_size cs) -> m' (wa a) = m (wa a)) ->
  rw_cells rsegs m' A cs.
Proof.
  intros m m' A cs [[Hwf (Ha & Hl & Hb)] (_ & _ & Hw)] AG.
  pose proof (cells_bytes_length cs Hwf) as L.
  split; [split; [exact Hwf|]|].
  - split; [exact Ha|]. split; [exact Hl|]. intros i Hi. unfold mrd. rewrite AG by (rewrite <- L; lia). apply Hb. exact Hi.
  - split; [lia|]. split; [lia|]. intros i Hi. unfold wview. rewrite AG by lia. apply Hw. exact Hi.
Qed.

Lemma HttpCat_agree : forall m m' hb,
  HttpCat m hb -> (forall a, XH_LO <= a < XH_HI -> m' (wa a) = m (wa a)) -> HttpCat m' hb.
Proof.
  intros m m' hb [C1 C2] AG. split.
  - eapply rw_cells_agree; [exact C1|]. intros a Ha. apply AG.
    assert (Z.of_nat (cells_size (HttpCatCells hb)) = 56) by (destruct hb; reflexivity).
    unfold XH_LO, XH_HI, G_HTTP_CAT in *. lia.
  - eapply rw_cells_agree; [exact C2|]. intros a Ha. apply AG.
    assert (Z.of_nat (cells_size (HttpCatGuardCells hb)) = 8) by (destruct hb; reflexivity).
    unfold XH_LO, XH_HI, G_HTTP_CAT_GUARD in *. lia.
Qed.
