Lemma HStat_agree : forall FT m m',
  ft_local FT -> HStat FT m -> (forall a, XH_LO <= a < XH_HI -> m' (wa a) = m (wa a)) -> HStat FT m'.
Proof.
  intros FT m m' FL [[hb HC] FZ] AG. split.
  - exists hb. eapply HttpCat_agree; eassumption.
  - destruct FZ as [Z0|B]; [left; eapply FieldTabZero_agree; eassumption | right; eapply FL; eassumption].
Qed.

