(* [comment removed for export] *)
Lemma pristine_agree : forall m m' lo hi,
  pristine m lo hi -> (forall a, lo <= a < hi -> m' (wa a) = m (wa a)) -> pristine m' lo hi.
Proof. intros m m' lo hi P AG a Ha. rewrite AG by exact Ha. apply P. exact Ha. Qed.

Lemma XImg_agree : forall m m',
  XImg m -> (forall a, (XRELRO_LO <= a < XRELRO_HI \/ XDATA_LO <= a < XDATA_HI) -> m' (wa a) = m (wa a)) -> XImg m'.
Proof.
  intros m m' [P1 P2] AG. split; (eapply pristine_agree; [eassumption|]); intros a Ha; apply AG; [left|right]; exact Ha.
Qed.

(* [comment removed for export] *)
Lemma wcells_facts : forall zs,
  length (flat_map le8z zs) = (8 * length zs)%nat
  /\ cells_wf (wcells zs)
  /\ cells_bytes (wcells zs) = flat_map le8z zs
  /\ cells_size (wcells zs) = (8 * length zs)%nat.
Proof.
  induction zs as [|z zs IH]; [repeat split; reflexivity|]. destruct IH as (L & W & B & S).
  cbn [flat_map length wcells map cells_wf cells_bytes cells_size cbytes csize]. fold (wcells zs).
  rewrite length_app, L, B, S. unfold le8z at 1. rewrite length_le8. repeat split; try lia. exact W.
Qed.

Lemma wcells_of_image : forall m A zs,
  pristine m A (A + 8 * Z.of_nat (length zs)) ->
  rw_bytes_b rsegs A (flat_map le8z zs) = true ->
  0 <= A -> A + 8 * Z.of_nat (length zs) <= 2^64 ->
  rw_cells rsegs m A (wcells zs).
Proof.
  intros m A zs P RB HA HL. destruct (wcells_facts zs) as (L & W & B & S).
  assert (RC : rw_cells rsegs m A [CB (length (flat_map le8z zs)) (flat_map le8z zs)]).
  { apply (rw_cells_image0 rsegs m A (flat_map le8z zs)); [| exact RB | exact HA | rewrite L; lia].
    intros a Ha. rewrite L in Ha. rewrite <- (Z_to_bv_bv_unsigned a). apply P. lia. }
  eapply rw_cells_recast; [exact RC | exact W | |].
  - rewrite B. cbn [cells_bytes cbytes]. rewrite app_nil_r. reflexivity.
  - rewrite S, <- L. cbn [cells_size csize]. lia.
Qed.

