Lemma chunk_of_XImg : forall m ac,
  XImg m ->
  (rw_bytes_b rsegs (fst ac) (flat_map le8z (snd ac))
   && (((XRELRO_LO <=? fst ac) && (fst ac + 8 * Z.of_nat (length (snd ac)) <=? XRELRO_HI))
       || ((XDATA_LO <=? fst ac) && (fst ac + 8 * Z.of_nat (length (snd ac)) <=? XDATA_HI))))%Z = true ->
  rw_cells rsegs m (fst ac) (wcells (snd ac)).
Proof.
  intros m [A zs] [P1 P2] Hb. cbn [fst snd] in *.
  apply andb_prop in Hb. destruct Hb as [RB R].
  unfold XRELRO_LO, XRELRO_HI, XDATA_LO, XDATA_HI in *.
  apply (wcells_of_image m A zs); [| exact RB | lia | lia].
  intros a Ha. apply Bool.orb_prop in R. destruct R as [R|R]; apply andb_prop in R; destruct R as [R1 R2];
    apply Z.leb_le in R1; apply Z.leb_le in R2; [apply P1 | apply P2]; lia.
Qed.

